from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP
import csv
import json
from datetime import datetime

CSV_PATH = Path('/app/orders.csv')
OUT_PATH = Path('/app/output.json')

def money(value):
    return format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), 'f')

def parse_amount(value):
    value = value.strip()
    return Decimal(value) if value else Decimal('0.00')

def normalize_date(value):
    value = value.strip()
    for fmt in ('%Y-%m-%d', '%m/%d/%Y'):
        try:
            return datetime.strptime(value, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    raise ValueError(f'Unsupported date format: {value!r}')

with CSV_PATH.open(newline='', encoding='utf-8-sig') as f:
    reader = csv.reader(
        f,
        delimiter='|',
        quotechar='"',
        escapechar='\\',
        doublequote=False,
    )
    header = [h.strip() for h in next(reader)]
    orders = []
    for raw_row in reader:
        if not raw_row:
            continue
        if len(raw_row) > len(header):
            extra = [v for v in raw_row[len(header):] if v.strip()]
            if extra:
                raise ValueError(f'Unexpected extra columns: {extra!r}')
            raw_row = raw_row[:len(header)]
        elif len(raw_row) < len(header):
            raw_row = raw_row + [''] * (len(header) - len(raw_row))
        row = {header[i]: raw_row[i].strip() for i in range(len(header))}
        row['OrderDate'] = normalize_date(row['OrderDate'])
        orders.append(row)

total_records = len(orders)
total_amount = sum((parse_amount(o['TotalAmount']) for o in orders), Decimal('0.00'))

status_counts = {}
for order in orders:
    status = order['Status']
    status_counts[status] = status_counts.get(status, 0) + 1
status_counts = dict(sorted(status_counts.items()))

monthly_data = {}
for order in orders:
    month = order['OrderDate'][:7]
    if month not in monthly_data:
        monthly_data[month] = {'revenue': Decimal('0.00'), 'order_count': 0}
    monthly_data[month]['revenue'] += parse_amount(order['TotalAmount'])
    monthly_data[month]['order_count'] += 1

monthly_revenue = [
    {
        'month': month,
        'revenue': money(data['revenue']),
        'order_count': data['order_count'],
    }
    for month, data in sorted(monthly_data.items())
]

orders_sorted = sorted(orders, key=lambda o: (o['Status'], int(o['OrderID'])))

customer_data = {}
for order in orders:
    name = order['CustomerName']
    if name not in customer_data:
        customer_data[name] = {'count': 0, 'spend': Decimal('0.00')}
    customer_data[name]['count'] += 1
    customer_data[name]['spend'] += parse_amount(order['TotalAmount'])

customers = [
    {
        'CustomerName': name,
        'OrderCount': data['count'],
        'TotalSpend': money(data['spend']),
    }
    for name, data in customer_data.items()
]
customers.sort(key=lambda c: c['CustomerName'])

report = {
    'summary': {
        'total_records': total_records,
        'total_amount': money(total_amount),
        'status_counts': status_counts,
        'monthly_revenue': monthly_revenue,
    },
    'orders': orders_sorted,
    'customers': customers,
}

OUT_PATH.write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(json.dumps(report, indent=2, ensure_ascii=False))
